class Tal():
    def __init__(self, tal):
        self.tal = tal

    def __str__(self):
	    return "från str: " + str(self.tal)

    def __repr__(self):
        return "från repr: " + str(self.tal)

def main():
    lista=[]
    dict = {}
    for i in range(5):
        objekt = Tal(i)
        lista.append(objekt)
        dict[i] = objekt

    print('lista', lista) 
    print('dict', dict)

    print('Element i lista:')
    for element in lista:
            print(element) 
    print('\nElement i dictionary:')
    for nyckel in dict.keys():
         print(dict[nyckel])

main()
